class Solution {
  public int maxFrequency(int[] nums, int k) {
    int base = 0;
    for (int x : nums) if (x == k) base++;
    int bestGain = 0;
    for (int v = 1; v <= 50; v++) {
      if (v == k) continue;
      int cur = 0;
      for (int x : nums) {
        cur = Math.max(cur, 0) + (x == v ? 1 : x == k ? -1 : 0);
        if (cur > bestGain) bestGain = cur;
      }
    }
    return base + bestGain;
  }
}
